.holo-card {
  width: 240px; height: 340px; border-radius: 20px; position: relative;
  overflow: hidden; animation: cardFloat 4s ease-in-out infinite;
  border: 1px solid rgba(255,255,255,0.15);
}
.holo-bg {
  position: absolute; inset: 0;
  background: linear-gradient(135deg, #1a1a3e 0%, #2d1b69 25%, #0f4c75 50%, #1a2a4a 75%, #2d1b69 100%);
  background-size: 400% 400%; animation: holoShift 6s ease infinite;
}
.holo-sheen {
  position: absolute; inset: 0;
  background: linear-gradient(105deg, transparent 30%, rgba(255,255,255,0.08) 45%, rgba(255,255,255,0.15) 50%, rgba(255,255,255,0.08) 55%, transparent 70%);
  background-size: 200% 200%; animation: sheenMove 3s ease-in-out infinite;
}
.holo-rainbow {
  position: absolute; inset: 0;
  background: linear-gradient(135deg, rgba(124,58,237,0.3), rgba(6,182,212,0.3), rgba(16,185,129,0.2), rgba(251,191,36,0.2), rgba(239,68,68,0.2), rgba(168,85,247,0.3));
  background-size: 300% 300%; animation: rainbowShift 4s ease infinite; mix-blend-mode: screen;
}
.holo-content {
  position: relative; z-index: 2; height: 100%; display: flex; flex-direction: column;
  align-items: center; justify-content: center; gap: 12px; padding: 1.5rem;
}
.holo-icon { font-size: 3rem; filter: drop-shadow(0 0 12px rgba(168,85,247,0.8)); }
.holo-title {
  font-family: monospace; font-size: 1.1rem; font-weight: 800; color: white; letter-spacing: 3px;
  text-transform: uppercase; text-shadow: 0 0 20px rgba(168,85,247,0.9), 0 0 40px rgba(6,182,212,0.5);
  animation: glitch 5s infinite;
}
.holo-sub { font-family: monospace; font-size: 0.7rem; color: rgba(255,255,255,0.5); letter-spacing: 2px; text-transform: uppercase; }
.holo-line { width: 80%; height: 1px; background: linear-gradient(90deg, transparent, rgba(168,85,247,0.8), transparent); }

@keyframes cardFloat { 0%,100% { transform: translateY(0) rotateX(0deg); } 50% { transform: translateY(-12px) rotateX(3deg); } }
@keyframes holoShift { 0%,100% { background-position: 0% 50%; } 50% { background-position: 100% 50%; } }
@keyframes sheenMove { 0% { background-position: -100% -100%; } 100% { background-position: 200% 200%; } }
@keyframes rainbowShift { 0%,100% { background-position: 0% 0%; } 50% { background-position: 100% 100%; } }
@keyframes glitch { 0%,90%,100% { text-shadow: 0 0 20px rgba(168,85,247,0.9); transform: none; } 92% { transform: translate(-2px, 0); text-shadow: 2px 0 #06b6d4, -2px 0 #ec4899; } 94% { transform: translate(2px, 0); text-shadow: -2px 0 #06b6d4, 2px 0 #ec4899; } 96% { transform: none; } }
